#!/usr/bin/env python3
# A deliberately weak sponge: rate = 3 bytes, capacity = 1 byte -> a 4-byte
# internal state. The permutation is a tiny invertible ARX round.
RATE, CAP = 3, 1
MASK = 0xffffffff

def perm(state):
    x = int.from_bytes(bytes(state), "little")
    for r in range(8):
        x = (x + ((x << 5) & MASK)) & MASK
        x ^= (x >> 7)
        x = ((x << 11) | (x >> 21)) & MASK
    return list(x.to_bytes(4, "little"))

def absorb(data):
    s = [0, 0, 0, 0]
    m = data + b"\x80"
    m += b"\x00" * ((RATE - len(m) % RATE) % RATE)
    for i in range(0, len(m), RATE):
        for j in range(RATE):
            s[j] ^= m[i + j]
        s = perm(s)
    return s

def sponge_hash(data):
    return bytes(absorb(data)[:RATE])

if __name__ == "__main__":
    for msg in (b"admin=false", b"role=user", b"guest"):
        print("%-12s -> %s" % (msg.decode(), sponge_hash(msg).hex()))
